<?php $title='Dashboard'; require __DIR__.'/includes/header.php'; $pdo=db(); if($user['role']==='admin'){$archives=(int)$pdo->query('SELECT COUNT(*) FROM archives')->fetchColumn();$payments=(int)$pdo->query('SELECT COUNT(*) FROM payments')->fetchColumn();$total=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments')->fetchColumn();$today=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(paid_at)=CURDATE()')->fetchColumn();$month=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments WHERE YEAR(paid_at)=YEAR(CURDATE()) AND MONTH(paid_at)=MONTH(CURDATE())')->fetchColumn();?><div class="page-head"><div><h1>Good day, <?=e($user['full_name'])?></h1><p class="muted">Overview of your notary office.</p></div><a class="btn" href="archive_add.php">+ Add archive</a></div><div class="grid grid-4"><div class="stat"><div class="label">Archives</div><div class="value"><?=$archives?></div></div><div class="stat"><div class="label">Payments</div><div class="value"><?=$payments?></div></div><div class="stat"><div class="label">Collected</div><div class="value"><?=CURRENCY.number_format($total,2)?></div></div><div class="stat"><div class="label">This month</div><div class="value"><?=CURRENCY.number_format($month,2)?></div><small class="muted">Today: <?=CURRENCY.number_format($today,2)?></small></div></div><?php }else{?><div class="page-head"><div><h1>Welcome, <?=e($user['full_name'])?></h1><p class="muted">Create a new archive or search existing records.</p></div></div><div class="grid grid-2"><div class="card"><h2>New archive</h2><p>Register an asset transaction and add its payment.</p><a class="btn" href="archive_add.php">Start archive</a></div><div class="card"><h2>Find an archive</h2><p>Search by reference number, payer name, or phone.</p><a class="btn light" href="archive_list.php">Search archives</a></div></div><?php } require __DIR__.'/includes/footer.php';

